<!-- This file is generated by AI. -->
<!--
  单个名称输入的对话框 (新建文件 / 新建文件夹 / 重命名 / 导入等复用)。

  约定: `onSubmit` 返回**非 null 字符串即视为失败**, 对话框保持打开并显示该错误 ——
  这样"名称已存在"这类校验结果能就地反馈, 不用调用方自己管错误状态。
-->
<script lang="ts">
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Input from './Input.svelte';

  let {
    title,
    label = '名称',
    initialValue = '',
    placeholder,
    hint,
    /** 只选中主文件名 (不含扩展名), 重命名时更顺手 */
    selectStem = false,
    submitLabel = '确定',
    /**
     * 就地校验 (返回错误信息或 null; 可以是异步的 —— 重名检查要问磁盘)。
     *
     * 与 `onSubmit` 的返回值**分工不同**: `validate` 判的是"这个字符串不合法 / 这个名字已经有了",
     * 打字时就能判出来, 提前禁用确定按钮比让用户敲完回车再被打回来好; `onSubmit` 的失败是
     * "落盘那一步失败了" (权限、重名已被别人占用), 只有提交后才知道。
     */
    validate,
    /** 返回错误信息或 null */
    onSubmit,
    onClose,
  }: {
    title: string;
    label?: string;
    initialValue?: string;
    placeholder?: string;
    hint?: string;
    selectStem?: boolean;
    submitLabel?: string;
    validate?: (name: string) => string | null | Promise<string | null>;
    onSubmit: (name: string) => Promise<string | null>;
    onClose: () => void;
  } = $props();

  /** 初值只在挂载时取一次 (对话框每次打开都是新实例), 包成 IIFE 表明这是有意的。 */
  let value = $state((() => initialValue)());
  let busy = $state(false);
  let error = $state<string | null>(null);
  let validationError = $state<string | null>(null);

  /**
   * 输入即校验。
   *
   * 带回拨令牌是因为校验异步而用户打字更快: 不丢弃过期结果的话, 先发出的那次校验后返回,
   * 显示的会是上一个名字的错误。
   */
  let validationToken = 0;

  $effect(() => {
    const trimmed = value.trim();
    const check = validate;
    // 还没输入时不报错 (一打开就写着"名称不能为空"很吵)
    if (!trimmed || !check) {
      validationError = null;
      return;
    }
    const token = ++validationToken;
    void (async () => {
      const result = await check(trimmed);
      if (token === validationToken) validationError = result;
    })();
  });

  const canSubmit = $derived(value.trim() !== '' && !busy && validationError === null);

  async function submit(): Promise<void> {
    if (!canSubmit) return;
    busy = true;
    error = null;
    try {
      const failure = await onSubmit(value.trim());
      if (failure) error = failure;
      else onClose();
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }
</script>

<AppDialog {title} size="small" closeOnBackdrop={!busy} {onClose}>
  <div class="settings-field">
    <span class="settings-label">{label}</span>
    <Input
      bind:value
      {placeholder}
      disabled={busy}
      autofocus
      {selectStem}
      onkeydown={(event) => {
        if (event.key !== 'Enter') return;
        event.preventDefault();
        void submit();
      }}
    />
  </div>

  {#if hint}
    <p class="prompt-hint">{hint}</p>
  {/if}
  <!-- 提交失败的信息盖在就地校验结果上面 (它是最新的) -->
  {#if error}
    <p class="prompt-error">{error}</p>
  {:else if validationError}
    <p class="prompt-error">{validationError}</p>
  {/if}

  {#snippet footer()}
    <Button onclick={onClose} disabled={busy}>取消</Button>
    <Button appearance="primary" onclick={() => void submit()} disabled={!canSubmit}>
      {busy ? '处理中…' : submitLabel}
    </Button>
  {/snippet}
</AppDialog>
